# Reviewed under AGENTS.md
import json
from pathlib import Path

base = Path(__file__).resolve().parent
inventory = json.loads((base / 'inventory.json').read_text())
# normalize counts to ints where possible
for sku, qty in list(inventory.items()):
    if isinstance(qty, str):
        try:
            inventory[sku] = int(qty)
        except ValueError:
            pass

rejected = []
lines = (base / 'transactions.txt').read_text().splitlines()
for lineno, raw in enumerate(lines, start=1):
    line = raw.strip()
    if not line:
        continue
    parts = line.split()
    if len(parts) != 3:
        continue
    op, sku, qty_s = parts
    try:
        qty = int(qty_s)
    except ValueError:
        continue
    op = op.lower()
    if op == 'add':
        inventory[sku] = inventory.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in inventory or inventory[sku] - qty < 0:
            rejected.append(lineno)
        else:
            inventory[sku] = inventory[sku] - qty
    else:
        continue

(base / 'inventory_after.json').write_text(json.dumps(inventory, indent=2) + '\n')
(base / 'rejected.txt').write_text(''.join(f'{n}\n' for n in rejected))
print('done', len(rejected))
